import { logger } from '../logger'
import { KeyChain } from './keychain'
import { LazyCredential, type Logger, type ResolvedAuth } from '@servicenow/sdk-api'
import { refreshAccessToken } from './OAuth'
import { getUISessionToken } from './basic-auth'
import { CookieJar } from 'tough-cookie'

const SERVICE = 'ServiceNow'
const keyChain = new KeyChain(SERVICE)

export type Credentials = {
    isDefault: boolean
    alias: string
    creds: Creds
}

export type KeyChainStore = {
    [alias: string]: Credentials
}

export type CredentialPreview = {
    isDefault: boolean
    instanceUrl: string
} & (
    | {
          type: 'basic'
          username: string
      }
    | {
          type: 'oauth'
      }
)

export const credentialProvider = async (credentialAlias: string | undefined): Promise<LazyCredential> => {
    const ciCreds = getCiCredentials()

    const createResolver = (getCredsFunc: () => Promise<Creds> | Creds) => {
        return async () => {
            const creds = await getCredsFunc()
            const session = await getUserSession(creds, logger)
            if (!session) {
                throw new Error('Unauthorized')
            }
            return userSessionToCredential(session)
        }
    }

    if (ciCreds) {
        // CI mode - use environment credentials
        return new LazyCredential(
            new URL(ciCreds.instanceUrl),
            createResolver(() => ciCreds)
        )
    }

    // Non-CI mode - use stored credentials
    const storedCredentials = await getStoredCredentials(credentialAlias)

    return new LazyCredential(
        new URL(storedCredentials.creds.instanceUrl),
        createResolver(() => getRefreshedCredentials(storedCredentials))
    )
}

export function userSessionToCredential(session: SessionOrToken): ResolvedAuth {
    if (session.type === 'oauth') {
        return {
            type: 'oauth',
            token: session.access_token,
        }
    }

    return {
        type: 'basic',
        token: session.userToken,
        cookie: getAuthCookie(session),
    }
}

export function getAuthCookie(auth: SessionOrToken) {
    if (auth.type === 'basic' && auth.cookie) {
        return auth.cookie.getCookieStringSync(auth.instanceUrl)
    }

    return undefined
}

function getCiCredentials(): Creds | undefined {
    if (process.env['SN_SDK_NODE_ENV'] === 'SN_SDK_CI_INSTALL') {
        const creds = getCIAuthConfig()
        logger.info(`Running in CI mode, using instance ${creds.instanceUrl}`)
        return creds
    }
    return undefined
}

async function getRefreshedCredentials(storedCredentials: Credentials): Promise<Creds> {
    const { creds, alias, isDefault } = storedCredentials
    if (creds.type === 'oauth') {
        const newTokens = await refreshAccessToken(creds, logger)
        if (newTokens) {
            const updatedCreds = {
                ...creds,
                ...newTokens,
            } as Creds
            await updateCredentials(alias, updatedCreds, isDefault)
            return updatedCreds
        }
    }
    return creds
}

export async function getCredentials(credentialAlias: string | undefined): Promise<Creds> {
    const ciCreds = getCiCredentials()
    if (ciCreds) {
        return ciCreds
    }

    const storedCredentials = await getStoredCredentials(credentialAlias)
    return getRefreshedCredentials(storedCredentials)
}

async function updateCredentials(alias: string, authInfo: Creds, isDefault: boolean): Promise<void> {
    const keyStore = (await getParsedCredentials()) ?? {}

    keyStore[alias] = {
        isDefault,
        alias,
        creds: authInfo,
    }
    await keyChain.setPassword(JSON.stringify(keyStore))
}

async function getStoredCredentials(alias: string | undefined): Promise<Credentials> {
    if (!alias) {
        const defaultCreds = await getDefaultCredentials()
        if (!defaultCreds) {
            throw new Error(
                'Default Credential has not been set, Please provide the credential alias to use or set a default by using "$now-sdk auth --use <alias>" command'
            )
        }
        return defaultCreds
    }

    const keyStore = await getParsedCredentials()
    if (!keyStore || !keyStore[alias]) {
        throw new Error(
            `Could not find stored credentials for alias: ${alias}, Please check the alias provided or save an alias using "$now-sdk auth --add <instance>" command`
        )
    }

    return keyStore[alias]
}

export async function storeCredentials(alias: string, authInfo: Creds, isDefault: boolean): Promise<void> {
    const keyStore = (await getParsedCredentials()) ?? {}

    const defaultCreds = Object.values(keyStore).find((creds) => creds.isDefault)

    keyStore[alias] = {
        isDefault: defaultCreds ? (defaultCreds.alias === alias ? true : isDefault) : true,
        alias,
        creds: authInfo,
    }

    // if new creds are set as default, remove the default flag from the previous default creds
    if (defaultCreds && defaultCreds.alias !== alias && isDefault) {
        keyStore[defaultCreds.alias]!.isDefault = false
    }

    await keyChain.setPassword(JSON.stringify(keyStore))
}

export async function updateDefaultCredential(alias: string) {
    logger.info(`Setting alias ${alias} as default ...`)
    const keyStore = await getParsedCredentials()
    if (!keyStore || !keyStore[alias]) {
        throw new Error(
            `No credentials found for alias ${alias}, Please check the alias provided or save an alias using "$now-sdk auth --add <instance>" command`
        )
    }

    const currentDefaultCreds = await getDefaultCredentials()

    if (currentDefaultCreds?.alias === alias) {
        logger.info(`alias ${alias} is already set as default`)
        return
    }

    if (currentDefaultCreds) {
        keyStore[currentDefaultCreds.alias]!.isDefault = false
    }
    keyStore[alias].isDefault = true

    await keyChain.setPassword(JSON.stringify(keyStore))
    logger.info(`Successfully set alias ${alias} as default`)
}

export async function getDefaultCredentials(): Promise<Credentials | undefined> {
    const keyStore = await getParsedCredentials()

    if (!keyStore) {
        return
    }

    return Object.values(keyStore).find((creds) => creds.isDefault)
}

export async function removeCredentials(alias: string): Promise<void> {
    if (process.env['NODE_ENV'] === 'test') {
        return
    }

    const keyStore = await getParsedCredentials()

    if (alias === 'all') {
        if (!keyStore) {
            return
        }

        logger.info(`Removing all stored credentials ...`)
        await keyChain.deletePassword()
        logger.info(`Successfully removed all stored credentials`)
        return
    }

    logger.info(`Removing credentials for alias: ${alias} ...`)
    if (!keyStore || !keyStore[alias]) {
        logger.info(`No credentials found for alias: ${alias}`)
        return
    }

    delete keyStore[alias]
    await keyChain.setPassword(JSON.stringify(keyStore))
    logger.info(`Successfully removed credentials for alias ${alias}`)
}

export async function fetchCredentials(): Promise<Map<string, CredentialPreview>> {
    if (process.env['NODE_ENV'] === 'test') {
        return new Map()
    }

    const keyStore = await getParsedCredentials()
    const storedCreds: Map<string, CredentialPreview> = new Map()
    if (!keyStore) {
        return storedCreds
    }

    Object.values(keyStore).forEach((creds) => {
        const { alias: storedAlias, credPreview } = getPreviewCredentials(creds)
        storedCreds.set(storedAlias, credPreview)
    })

    return storedCreds
}

function getPreviewCredentials(cred: Credentials): { alias: string; credPreview: CredentialPreview } {
    const { alias, isDefault, creds } = cred

    if (creds.type === 'oauth') {
        return { alias, credPreview: { type: creds.type, instanceUrl: creds.instanceUrl, isDefault } }
    }
    return {
        alias,
        credPreview: { type: creds.type, instanceUrl: creds.instanceUrl, isDefault, username: creds.username },
    }
}

async function getParsedCredentials(): Promise<KeyChainStore | undefined> {
    const currentPassword = await keyChain.getPassword()
    return currentPassword ? (JSON.parse(currentPassword) as KeyChainStore) : undefined
}

const getCIAuthConfig = (): Creds => {
    return {
        type: 'basic',
        instanceUrl: process.env['SN_SDK_INSTANCE_URL'] as string,
        username: process.env['SN_SDK_USER'] as string,
        password: process.env['SN_SDK_USER_PWD'] as string,
    }
}

export type BasicCred = {
    instanceUrl: string
    type: 'basic'
    username: string
    password: string
}

export type OAuthCred = {
    instanceUrl: string
    type: 'oauth'
    access_token: string
    token_type: string
    refresh_token: string
    expires_at: number
}

export type Creds = BasicCred | OAuthCred

export type UserSession = {
    instanceUrl: string
    type: 'basic'
    userToken?: string
    cookie?: CookieJar
}

export type AccessToken = {
    instanceUrl: string
    type: 'oauth'
    access_token: string
    token_type: string
}

export type SessionOrToken = UserSession | AccessToken

export async function getSessionToken(creds: Creds, logger?: Logger): Promise<SessionOrToken | undefined> {
    const { instanceUrl, type } = creds

    if (type === 'basic') {
        const { username, password } = creds

        const session = await getUISessionToken({ instanceUrl, username, password }, logger)
        if (!session) {
            return
        }
        return session
    }

    return { instanceUrl, type, access_token: creds.access_token, token_type: creds.token_type }
}

export async function getUserSession(creds: Creds, logger?: Logger): Promise<UserSession | undefined> {
    const session = await getSessionToken(creds, logger)

    if (!session) {
        return
    }

    if (session.type === 'basic') {
        return session
    }

    //get csrf token and check if the app is already installed
    const cookieJar = new CookieJar()
    const csrfToken = await getCSRFToken(session, cookieJar)

    return {
        type: 'basic',
        instanceUrl: session.instanceUrl,
        cookie: cookieJar,
        userToken: csrfToken || '',
    }
}

/**
 *
 * The ScopedAppUploadProcessor does CSRF token validation and checks for the presence of a user token in the request.
 * in case of OAuth we need to make a request to get the CSRF token
 *
 */

async function getCSRFToken(auth: AccessToken, cookieJar: CookieJar): Promise<string | undefined> {
    try {
        // Request 1, to get CSRF token
        const responseOne = await fetch(`${auth.instanceUrl}/angular.do?sysparm_type=get_user`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
        })

        if (!responseOne.ok) {
            return undefined
        }

        responseOne.headers.getSetCookie().forEach((cookie) => {
            cookieJar.setCookieSync(cookie, auth.instanceUrl)
        })

        // Request 2, to attach a session to the CSRF token
        const responseTwo = await fetch(
            `${auth.instanceUrl}/api/now/table/sys_scope?${new URLSearchParams({
                sysparm_fields: 'sys_id,sys_class_name',
                sysparm_limit: '1',
            }).toString()}`,
            {
                method: 'GET',
                headers: {
                    Cookie: cookieJar.getCookieStringSync(auth.instanceUrl),
                    Authorization: `${auth.token_type} ${auth.access_token}`,
                },
            }
        )

        responseTwo.headers.getSetCookie().forEach((cookie) => {
            cookieJar.setCookieSync(cookie, auth.instanceUrl)
        })

        // Request 3, to get a new CSRF token that will be used for the upload
        const responseThree = await fetch(`${auth.instanceUrl}/angular.do?sysparm_type=get_user`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                Cookie: cookieJar.getCookieStringSync(auth.instanceUrl),
            },
        })

        if (responseThree.status === 401 && responseThree.headers.has('x-usertoken-response')) {
            return responseThree.headers.get('x-usertoken-response') as string
        }

        responseThree.headers.getSetCookie().forEach((cookie) => {
            cookieJar.setCookieSync(cookie, auth.instanceUrl)
        })
    } catch (e) {
        console.error('Error fetching CSRF token:', e)
        // fall through to return empty string below
    }

    return undefined
}
